INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000051', 'Buoyancy', 'Engineering & Technology', 'Fluid Mechanics', 'Technical Concept', 'The net upward force exerted by a fluid on an immersed or floating body due to the pressure distribution in the fluid.', 'Archimedes'' principle, displaced-fluid volume, centre of buoyancy and floating equilibrium.', 'Hydrostatic pressure; displaced volume; force equilibrium.', 'Buoyant force equals the weight of displaced fluid for a body in a static fluid. Floating equilibrium depends on the relative locations of weight and buoyancy.', 'Hydrostatics; pressure forces; Hydrostatic pressure; displaced volume; force equilibrium; Fluid Mechanics', 'Active'), ('KCR_000052', 'Continuity', 'Engineering & Technology', 'Fluid Mechanics', 'Technical Concept', 'The mass-conservation relation requiring that mass entering, leaving and accumulating within a fluid system satisfy conservation of mass.', 'Control-volume continuity, steady/unsteady flow, incompressible simplification and area-velocity relationships.', 'Mass conservation; flux balance; continuity.', 'For steady incompressible one-dimensional flow, volumetric flow rate is conserved along a streamtube in the absence of sources or sinks, giving A₁V₁=A₂V₂.', 'Mass conservation; control volumes; flux balance; continuity; Fluid Mechanics', 'Active'), ('KCR_000053', 'Reynolds number', 'Engineering & Technology', 'Fluid Mechanics', 'Principle / Criterion', 'A dimensionless ratio comparing inertial effects with viscous effects in fluid flow.', 'Re = ρVL/μ, characteristic length/velocity choices, similarity and flow-regime interpretation.', 'Dimensional analysis; inertial-viscous balance; dynamic similarity.', 'Reynolds number helps characterize flow regimes and dynamic similarity. Critical values depend on geometry, disturbance level and flow configuration rather than being universal.', 'Dimensional analysis; viscosity; inertial-viscous balance; dynamic similarity; Fluid Mechanics', 'Active'), ('KCR_000054', 'Head loss and pipe-flow analysis', 'Engineering & Technology', 'Fluid Mechanics', 'Method / Process', 'Analysis of pressure or energy losses associated with fluid flow through pipes and fittings.', 'Darcy-Weisbach equation, friction factor, minor losses, hydraulic grade/energy lines and flow regimes.', 'Energy conservation; friction; hydraulic resistance; efficiency.', 'Pipe-flow analysis quantifies major and minor head losses and their effect on required pressure head or pumping power.', 'Reynolds number; viscosity; energy equation', 'Active'), ('KCR_000055', 'Truss and beam analysis', 'Engineering & Technology', 'Structural Analysis I', 'Method / Process', 'Structural analysis procedures for determining internal forces and reactions in idealized trusses and beams under applied loads.', 'Equilibrium, free-body diagrams, axial truss forces, shear and bending moment in beams.', 'Equilibrium; load path; internal force; structural determinacy.', 'Truss and beam analysis converts external loading and supports into internal force resultants using equilibrium and stated idealizations.', 'Statics; structural equilibrium; Equilibrium; load path; internal force; structural determinacy', 'Active'), ('KCR_000056', 'Moment-area theorem', 'Engineering & Technology', 'Structural Analysis I', 'Method / Process', 'Beam-deflection relations that connect changes in slope and deflection to areas and first moments of the M/EI diagram.', 'Theorem 1 for slope change, theorem 2 for tangential deviation, boundary conditions and sign conventions.', 'Curvature; integration; compatibility.', 'The moment-area method integrates beam curvature through geometric properties of the bending-moment diagram to obtain slope and deflection.', 'Flexure; beam deflection; Curvature; integration; compatibility; Structural Analysis I', 'Active'), ('KCR_000057', 'Virtual work', 'Engineering & Technology', 'Structural Analysis I', 'Technical Concept', 'An analytical method that uses work equivalence under a compatible virtual displacement to determine structural responses.', 'Virtual displacements, external/internal virtual work, unit-load method and displacement calculation.', 'Equilibrium; compatibility; work-energy relations.', 'The virtual-work method relates virtual external work to virtual internal work and can determine displacements or reactions in structures.', 'Equilibrium; beam/truss analysis; compatibility; work-energy relations; Structural Analysis I', 'Active'), ('KCR_000058', 'Influence-line construction', 'Engineering & Technology', 'Structural Analysis I', 'Technical Concept', 'A graphical or analytical representation showing how a response quantity at a specified location varies as a moving load changes position.', 'Influence lines for reactions, shear, moment and other responses in determinate structures.', 'Moving loads; structural response; position dependence.', 'Influence lines identify the variation of a response function as a load moves through a structure and are used to locate critical load positions.', 'Structural analysis; moving loads; structural response; position dependence; Structural Analysis I', 'Active'), ('KCR_000059', 'Slope-deflection', 'Engineering & Technology', 'Structural Analysis I', 'Technical Concept', 'A displacement-based structural analysis method relating member end moments to end rotations, translations and fixed-end actions.', 'Member stiffness, end rotations, joint translations, fixed-end moments and compatibility equations.', 'Stiffness; compatibility; equilibrium.', 'The slope-deflection equations express member end moments in terms of joint displacements and member stiffness under small-deformation structural assumptions.', 'Beam analysis; structural stiffness; Stiffness; compatibility; equilibrium; Structural Analysis I', 'Active'), ('KCR_000060', 'Atterberg limits', 'Engineering & Technology', 'Geotechnical Engineering', 'Technical Concept', 'Empirical moisture-content limits used to characterize the consistency and plasticity range of fine-grained soils.', 'Liquid limit, plastic limit, shrinkage limit, plasticity index and consistency states.', 'Consistency; plasticity; water-content dependence.', 'Atterberg limits describe changes in consistency of fine-grained soils with moisture content and support soil classification and engineering assessment.', 'Soil index properties; soil classification; Consistency; plasticity; water-content dependence; Geotechnical Engineering', 'Active'), ('KCR_000061', 'Darcy''s law', 'Engineering & Technology', 'Geotechnical Engineering', 'Principle / Criterion', 'A constitutive relation stating that, under laminar saturated porous-media flow conditions, discharge is proportional to hydraulic gradient and hydraulic conductivity.', 'Hydraulic head, gradient, hydraulic conductivity, discharge/flux and applicability limits.', 'Potential gradient; hydraulic conductivity; porous-media flow.', 'Darcy''s law relates specific discharge to hydraulic gradient through hydraulic conductivity. Its common form assumes continuum-scale, laminar flow through saturated porous media.', 'Groundwater flow; hydraulic conductivity; Potential gradient; porous-media flow; Geotechnical Engineering', 'Active'), ('KCR_000062', 'Consolidation settlement', 'Engineering & Technology', 'Geotechnical Engineering; Foundation Engineering', 'Technical Concept', 'Time-dependent settlement of a saturated or nearly saturated soil caused by dissipation of excess pore-water pressure and associated volume change under sustained loading.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Consolidation settlement.', 'Consolidation settlement occurs as excess pore pressure dissipates and effective stress increases. One-dimensional consolidation theory describes the time-dependent response under its stated assumptions.', 'Effective stress; compressibility; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Consolidation settlement', 'Active'), ('KCR_000063', 'Mohr-Coulomb failure criterion', 'Engineering & Technology', 'Geotechnical Engineering', 'Principle / Criterion', 'A frictional failure criterion relating shear strength of soil or rock to effective normal stress, cohesion and friction angle.', 'τf = c'' + σ''n tanφ'' for effective-stress form, failure envelope and drained/undrained interpretation.', 'Shear strength; effective stress; friction; cohesion.', 'The Mohr-Coulomb criterion approximates failure strength with a linear envelope in normal-stress space. Parameters and stress basis depend on drainage and testing conditions.', 'Shear strength; effective stress; friction; cohesion; Geotechnical Engineering', 'Active'), ('KCR_000064', 'Lateral earth pressure', 'Engineering & Technology', 'Geotechnical Engineering', 'Technical Concept', 'The pressure exerted by soil against a retaining or embedded structure due to soil self-weight, surcharge, groundwater and other actions.', 'Active, passive and at-rest states, earth-pressure coefficients, wall friction and groundwater effects.', 'Stress state; equilibrium; soil-structure interaction.', 'Lateral earth pressure depends on soil properties, wall movement, geometry, drainage and surcharge. Rankine and Coulomb methods represent common idealized analyses.', 'Mohr-Coulomb; retaining structures; Stress state; equilibrium; soil-structure interaction; Geotechnical Engineering', 'Active'), ('KCR_000065', 'Demand forecasting', 'Engineering & Technology', 'Environmental Engineering; Water Resources Engineering', 'Method / Process', 'Estimation of future demand for a resource or service from historical observations, explanatory variables, assumptions, and uncertainty, used to support planning and design.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Demand forecasting.', 'Water-demand forecasting combines demographic and consumption assumptions to estimate future average and peak requirements for system planning.', 'Water demand; planning; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Demand forecasting', 'Active'), ('KCR_000066', 'Filtration', 'Engineering & Technology', 'Environmental Engineering', 'Method / Process', 'A water or wastewater treatment process that removes suspended or particulate matter by passing fluid through a porous filter medium.', 'Media filtration, straining, adsorption contributions, head loss, backwashing and filtration performance.', 'Particle removal; hydraulic resistance; treatment performance.', 'Filtration separates particles through mechanisms including straining, interception and attachment. Performance depends on media, particle characteristics, loading and operating conditions.', 'Water treatment; particle removal; hydraulic resistance; treatment performance; Environmental Engineering', 'Active'), ('KCR_000067', 'Sewer design', 'Engineering & Technology', 'Environmental Engineering', 'Method / Process', 'Engineering design of sewer systems to collect and convey wastewater safely and reliably to treatment or disposal facilities.', 'Flow estimation, pipe sizing, hydraulic grade, self-cleansing considerations, minimum/maximum velocities and system layout.', 'Public health; hydraulic capacity; reliability; gravity flow.', 'Sewer design balances projected wastewater flows, hydraulic capacity, constructability, maintenance and public-health requirements under applicable design criteria.', 'Wastewater collection; open-channel/pipe flow; Public health; hydraulic capacity; reliability; gravity flow', 'Active'), ('KCR_000068', 'Activated sludge process', 'Engineering & Technology', 'Environmental Engineering', 'Method / Process', 'A suspended-growth biological wastewater-treatment process in which microorganisms oxidize biodegradable pollutants in an aerated reactor followed by solids separation.', 'Aeration, biomass concentration, substrate removal, secondary clarification, sludge age and return/waste activated sludge.', 'Biological oxidation; mass balance; microbial growth; solids separation.', 'Activated sludge uses controlled microbial growth to remove biodegradable organic matter and, in suitable configurations, nitrogen and phosphorus.', 'Biological treatment; aeration; microbial kinetics', 'Active'), ('KCR_000069', 'Solid-waste management', 'Engineering & Technology', 'Environmental Engineering', 'Technical Concept', 'The systematic handling of solid wastes through generation reduction, segregation, collection, transport, processing, recovery and final disposal.', 'Waste characterization, collection, recycling/material recovery, biological treatment, thermal treatment and engineered disposal.', 'Waste hierarchy; pollution prevention; resource recovery; public health.', 'Solid-waste management applies a hierarchy of prevention, reuse, recovery, treatment and disposal while controlling environmental and health risks.', 'Waste hierarchy; resource recovery; pollution prevention; public health; Environmental Engineering', 'Active'), ('KCR_000070', 'Sight distance', 'Engineering & Technology', 'Transportation Engineering', 'Technical Concept', 'The roadway length over which a driver can see an object or roadway feature sufficiently far ahead to perform a required manoeuvre safely.', 'Stopping, passing and decision sight distance; driver perception-reaction, speed, grade and geometric constraints.', 'Safety; visibility; human factors; geometric design.', 'Sight distance criteria ensure that drivers have adequate visible roadway for the manoeuvre considered under specified design assumptions.', 'Highway geometric design; stopping sight distance; Safety; visibility; human factors; geometric design', 'Active'), ('KCR_000071', 'Super elevation', 'Engineering & Technology', 'Transportation Engineering', 'Technical Concept', 'The transverse slope provided on a roadway curve to assist in counteracting lateral acceleration associated with vehicle motion.', 'Superelevation rate, side friction, design speed, radius, runoff and transition.', 'Lateral stability; drainage; geometric transition; safety.', 'Superelevation redistributes lateral forces on horizontal curves. Design balances superelevation, side friction and operating/design speed within applicable standards.', 'Horizontal curves; side friction; Lateral stability; drainage; geometric transition; safety', 'Active'), ('KCR_000072', 'Traffic flow and control', 'Engineering & Technology', 'Transportation Engineering', 'Method / Process', 'Analysis and management of the movement of vehicles and people on transportation networks using flow relationships and control strategies.', 'Flow, speed, density, fundamental diagrams, intersections, signals, capacity and control measures.', 'Mobility; safety; capacity; accessibility; efficiency.', 'Traffic-flow analysis characterizes relationships among speed, flow and density, while control systems manage intersections and network operations.', 'Traffic engineering; transportation operations; Mobility; safety; capacity; accessibility', 'Active'), ('KCR_000073', 'Bitumen testing', 'Engineering & Technology', 'Transportation Engineering', 'Method / Process', 'Laboratory characterization of bituminous binders through standardized tests of consistency, viscosity, temperature susceptibility and related properties.', 'Penetration, ductility, softening point, viscosity, flash/fire point and temperature susceptibility, as applicable to the specification.', 'Material characterization; temperature dependence; quality control; durability.', 'Bitumen testing determines binder properties needed for specification, quality control and pavement-material selection; individual test applicability depends on the binder type and governing standard.', 'Pavement materials; binder properties; Material characterization; temperature dependence; quality control; durability', 'Active'), ('KCR_000074', 'Flexible pavement design', 'Engineering & Technology', 'Transportation Engineering', 'Method / Process', 'Design of layered pavement systems in which wheel loads are distributed through bituminous and granular layers over the subgrade.', 'Traffic loading, material properties, layer thicknesses, subgrade strength, drainage, fatigue and rutting considerations.', 'Load distribution; durability; material efficiency; serviceability.', 'Flexible-pavement design selects layer materials and thicknesses to meet structural and functional performance requirements over the design period.', 'Pavement materials; traffic loading; structural design', 'Active'), ('KCR_000075', 'Gantt charts', 'Engineering & Technology', 'Construction Planning & Management', 'Method / Process', 'A time-scaled project scheduling representation showing activities, durations and their planned timing.', 'Activities, durations, start/finish dates, overlaps, milestones and progress tracking.', 'Sequencing; visibility; schedule control.', 'Gantt charts communicate planned activity timing and progress but do not by themselves determine the mathematically critical path.', 'Project scheduling; activities; Sequencing; visibility; schedule control; Construction Planning & Management', 'Active'), ('KCR_000076', 'Crashing', 'Engineering & Technology', 'Construction Planning & Management', 'Technical Concept', 'A schedule-compression technique that reduces activity durations by applying additional resources or cost, subject to technical feasibility.', 'Normal/crash durations and costs, cost slopes, critical paths and incremental time-cost trade-offs.', 'Time-cost trade-off; critical-path focus; resource allocation.', 'Crashing shortens project duration by accelerating selected activities, normally beginning with cost-effective activities on the current critical path.', 'CPM; critical path; cost control', 'Active'), ('KCR_000077', 'Resource levelling', 'Engineering & Technology', 'Construction Planning & Management', 'Method / Process', 'A scheduling process that adjusts activity timing to resolve resource over-allocation while respecting stated project constraints.', 'Resource availability, activity priorities, float, sequencing and schedule impacts.', 'Resource constraints; feasibility; schedule stability.', 'Resource levelling modifies activity timing to produce a feasible resource profile and may increase project duration when resources are constrained.', 'Project scheduling; resource allocation; Resource constraints; feasibility; schedule stability; Construction Planning & Management', 'Active'), ('KCR_000078', 'Depreciation and cost control', 'Engineering & Technology', 'Construction Planning & Management', 'Method / Process', 'Methods for allocating the depreciable cost of assets over their useful lives and monitoring project costs against budgets.', 'Straight-line and declining-balance methods, book value, useful life, residual value, cost variance and budget control.', 'Lifecycle costing; accounting allocation; budget control.', 'Depreciation allocates asset cost over an accounting/useful-life period; cost control compares actual and committed costs with planned budgets and forecasts.', 'Construction economics; lifecycle cost; Lifecycle costing; accounting allocation; budget control; Construction Planning & Management', 'Active'), ('KCR_000079', 'Equipment selection and productivity', 'Engineering & Technology', 'Construction Planning & Management', 'Method / Process', 'Selection and operational assessment of construction equipment based on required work, capacity, cycle time, site conditions and economic constraints.', 'Equipment capacity, cycle time, utilization, production rate, operating cost and site compatibility.', 'Productivity; resource efficiency; safety; lifecycle economics.', 'Equipment productivity depends on machine capability, cycle conditions, utilization and site constraints. Selection should consider production, cost, reliability and safe operation.', 'Construction equipment; productivity; resource efficiency; safety; lifecycle economics; Construction Planning & Management', 'Active'), ('KCR_000080', 'Errors', 'Engineering & Technology', 'Surveying & Geomatics', 'Technical Concept', 'Deviations of measured or computed quantities from an accepted reference or true/accepted value, including systematic and random components.', 'Accuracy, precision, systematic/random error, propagation, uncertainty and error detection.', 'Measurement quality; uncertainty; repeatability; error propagation.', 'Surveying error analysis distinguishes systematic effects, random variation and blunders and applies appropriate checks, corrections and uncertainty assessment.', 'Measurement; uncertainty; Measurement quality; repeatability; error propagation; Surveying & Geomatics', 'Active'), ('KCR_000081', 'Benchmarks', 'Engineering & Technology', 'Surveying & Geomatics', 'Technical Concept', 'Reference points with known or established elevations used to control vertical surveying and transfer elevation information.', 'Permanent/temporary benchmarks, datum, reduced levels, levelling networks and monumentation.', 'Reference frames; traceability; control; consistency.', 'Benchmarks provide stable vertical references from which elevations can be measured or transferred within a defined datum and control network.', 'Levelling; geodetic datum; Reference frames; traceability; control; consistency', 'Active'), ('KCR_000082', 'Angular measurement', 'Engineering & Technology', 'Surveying & Geomatics', 'Technical Concept', 'Determination of horizontal or vertical angles between survey lines or directions using appropriate angular-measurement instruments.', 'Theodolites/total stations, centering, face observations, repetition, direction measurement and error control.', 'Geometric reference; precision; redundancy; instrument calibration.', 'Survey angular measurement determines directions or angles relative to a defined reference and uses observation procedures to reduce instrumental and observational error.', 'Survey instruments; measurement errors; Geometric reference; precision; redundancy; instrument calibration', 'Active'), ('KCR_000083', 'Horizontal and vertical curves', 'Engineering & Technology', 'Surveying & Geomatics', 'Technical Concept', 'Geometric transition elements used to connect roadway alignments while controlling changes in direction and grade.', 'Simple/compound horizontal curves, circular elements, transition curves, vertical parabolic curves and sight-distance considerations.', 'Geometric continuity; safety; comfort; visibility.', 'Horizontal curves transition plan alignment and vertical curves transition grades. Their geometry is selected to meet speed, visibility, drainage and comfort criteria.', 'Highway geometric design; sight distance; Geometric continuity; safety; comfort; visibility', 'Active'), ('KCR_000084', 'GNSS/GPS and GIS applications', 'Engineering & Technology', 'Surveying & Geomatics', 'Technical Concept', 'Use of satellite-based positioning and geographic information systems to acquire, reference, manage, analyze and visualize spatial data.', 'GNSS positioning, coordinate reference systems, accuracy/error sources, GIS layers, spatial queries and mapping.', 'Spatial reference; interoperability; positioning accuracy; spatial analysis.', 'GNSS provides positioning from satellite signals, while GIS organizes and analyzes geographically referenced data. GPS is one GNSS constellation, not a synonym for all GNSS.', 'GNSS; GIS; coordinate systems', 'Active'), ('KCR_000085', 'Control volumes', 'Engineering & Technology', 'Engineering Thermodynamics; Hydraulics and Hydraulic Engineering', 'Method / Process', 'A defined region in space used for applying conservation equations to mass, momentum, and energy crossing its boundary.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Control volumes.', 'Control-volume analysis converts conservation laws into balances on an open system by accounting for accumulation and fluxes across the control surface.', 'Conservation laws; fluid systems; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Control volumes', 'Active'), ('KCR_000086', 'Energy equation', 'Engineering & Technology', 'Engineering Thermodynamics', 'Method / Process', 'A statement of energy conservation applied to a thermodynamic system or control volume.', 'Internal, kinetic and potential energy, heat transfer, work, mass-flow energy and steady-flow simplifications.', 'Energy conservation; work/heat interactions; property accounting.', 'The first-law energy equation accounts for energy storage and transfer through heat, work and mass. Specific forms depend on the system boundary and assumptions.', 'First law; control volumes; Energy conservation; work/heat interactions; property accounting; Engineering Thermodynamics', 'Active'), ('KCR_000087', 'Second-law analysis', 'Engineering & Technology', 'Engineering Thermodynamics', 'Method / Process', 'Thermodynamic analysis based on the second law, including entropy balance and restrictions on energy-conversion processes.', 'Entropy balance, irreversibility, entropy generation, reversible/irreversible processes and efficiency limits.', 'Entropy; irreversibility; directionality; maximum performance.', 'Second-law analysis determines the direction and quality of energy transformations and quantifies irreversibility through entropy generation.', 'Entropy; second law; irreversibility; directionality; maximum performance; Engineering Thermodynamics', 'Active'), ('KCR_000088', 'Entropy generation', 'Engineering & Technology', 'Engineering Thermodynamics', 'Technical Concept', 'The production of entropy associated with irreversible processes within a system or control volume.', 'Entropy balance, heat transfer across finite temperature differences, friction, mixing and other irreversibilities.', 'Irreversibility; entropy production; lost work/exergy.', 'Entropy generation is non-negative for real processes and provides a quantitative measure of irreversibility under the second law.', 'Second law; exergy; Irreversibility; entropy production; lost work/exergy; Engineering Thermodynamics', 'Active'), ('KCR_000089', 'Carnot cycle', 'Engineering & Technology', 'Engineering Thermodynamics', 'Technical Concept', 'An ideal reversible heat-engine cycle consisting of two isothermal and two reversible adiabatic (isentropic) processes between two thermal reservoirs.', 'Isothermal expansion/compression, isentropic expansion/compression and maximum reversible efficiency.', 'Reversibility; temperature limits; efficiency bound.', 'The Carnot cycle establishes the maximum theoretical thermal efficiency between two reservoirs, dependent only on their absolute temperatures.', 'Second law; reversible processes; Reversibility; temperature limits; efficiency bound; Engineering Thermodynamics', 'Active'), ('KCR_000090', 'Velocity and acceleration fields', 'Engineering & Technology', 'Fluid Mechanics & Machinery', 'Technical Concept', 'Spatial and temporal fields describing fluid-particle velocity and acceleration throughout a flow domain.', 'Eulerian velocity field, material acceleration, local and convective acceleration, streamlines.', 'Kinematics; spatial gradients; material derivative.', 'Fluid kinematics describes motion without requiring a force balance. Material acceleration is obtained from the material derivative of the velocity field.', 'Fluid kinematics; material derivative; Kinematics; spatial gradients; Fluid Mechanics & Machinery', 'Active'), ('KCR_000091', 'Navier-Stokes equation', 'Engineering & Technology', 'Fluid Mechanics & Machinery', 'Method / Process', 'The momentum-conservation equation for a continuum fluid, with terms determined by density, pressure, body forces and constitutive behaviour.', 'Continuity coupling, pressure, viscous stresses, body forces, incompressible simplifications and boundary conditions.', 'Momentum conservation; constitutive modelling; viscosity.', 'The Navier-Stokes equations describe momentum balance for Newtonian fluids under the relevant continuum assumptions; solvability depends strongly on geometry and boundary conditions.', 'Momentum conservation; viscosity; continuity', 'Active'), ('KCR_000092', 'Boundary layers', 'Engineering & Technology', 'Fluid Mechanics & Machinery; Fluid Flow and Heat Transfer', 'Technical Concept', 'Thin regions adjacent to solid surfaces in which viscous effects produce strong velocity gradients and influence momentum, heat, or mass transfer.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Boundary layers.', 'Boundary-layer theory exploits the thinness of near-wall viscous regions to simplify high-Reynolds-number flows and predict shear and separation behaviour.', 'Reynolds number; viscosity; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Boundary layers', 'Active'), ('KCR_000093', 'Pelton and Francis turbines', 'Engineering & Technology', 'Fluid Mechanics & Machinery', 'Technical Concept', 'Hydraulic turbine types represented by Pelton impulse turbines and Francis reaction turbines for converting water energy into shaft power.', 'Pelton jet/bucket interaction; Francis runner, pressure change, head, flow rate, efficiency and operating range.', 'Energy conversion; hydraulic efficiency; flow control; mechanical power.', 'Pelton turbines extract energy primarily from high-velocity jets and are suited to high-head applications; Francis turbines are reaction turbines commonly used over moderate head/flow ranges.', 'Hydraulic turbines; energy equation; Energy conversion; hydraulic efficiency; flow control; mechanical power', 'Active'), ('KCR_000094', 'Centrifugal pumps', 'Engineering & Technology', 'Fluid Mechanics & Machinery; Hydraulics and Hydraulic Engineering', 'Technical Concept', 'Rotodynamic pumps that impart energy to a fluid primarily through the action of a rotating impeller, converting mechanical energy into fluid pressure and head.', 'Concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Centrifugal pumps.', 'Centrifugal pumps convert shaft power into fluid energy and operate at a system-dependent intersection of pump and system characteristics.', 'Rotodynamic pumps; head loss; Defining mechanism/properties; governing conditions; assumptions and limitations; application/performance criteria for Centrifugal pumps', 'Active'), ('KCR_000095', 'Grashof''s law', 'Engineering & Technology', 'Kinematics of Machinery', 'Principle / Criterion', 'A kinematic criterion for planar four-bar linkages relating link lengths to the possibility of continuous rotation of at least one link.', 'Shortest/longest/other link lengths, S+L ≤ P+Q criterion and limiting cases.', 'Kinematic feasibility; link geometry; mobility.', 'For the classical four-bar mechanism under the usual planar-link assumptions, S+L≤P+Q identifies Grashof linkages capable of at least one full rotation.', 'Four-bar mechanisms; linkage geometry; Kinematic feasibility; link geometry; mobility; Kinematics of Machinery', 'Active'), ('KCR_000096', 'Instantaneous centers', 'Engineering & Technology', 'Kinematics of Machinery', 'Technical Concept', 'Points or centers in planar rigid-body motion about which the relative velocity between two bodies is instantaneously equivalent to rotation.', 'Relative motion, Kennedy''s theorem, velocity relationships and construction methods.', 'Relative kinematics; rigid-body motion; instantaneous rotation.', 'Instantaneous centers provide a geometric method for relating velocities of connected rigid bodies at a given instant.', 'Planar kinematics; relative velocity; Relative kinematics; rigid-body motion; instantaneous rotation; Kinematics of Machinery', 'Active'), ('KCR_000097', 'Cam displacement diagrams', 'Engineering & Technology', 'Kinematics of Machinery', 'Method / Process', 'Graphs relating follower displacement, velocity, acceleration or related motion variables to cam angle or time.', 'Follower motion laws, rise/dwell/return, simple harmonic/cycloidal/polynomial motion and motion continuity.', 'Prescribed motion; continuity; acceleration control; kinematics.', 'Cam displacement diagrams define follower motion as a function of cam position and support selection of motion laws that control velocity and acceleration characteristics.', 'Cams; follower motion; Prescribed motion; continuity; acceleration control; kinematics', 'Active'), ('KCR_000098', 'Epicyclic gear trains', 'Engineering & Technology', 'Kinematics of Machinery', 'Technical Concept', 'Gear arrangements in which one or more gears rotate about axes that themselves move relative to a fixed frame.', 'Sun, planet, ring and carrier elements; relative motion; speed ratios and torque relationships.', 'Relative rotation; velocity ratio; compact power transmission.', 'Epicyclic trains derive speed and torque relationships from relative motion between gear elements and the carrier, enabling compact transmission arrangements.', 'Gear trains; relative motion; Relative rotation; velocity ratio; compact power transmission; Kinematics of Machinery', 'Active'), ('KCR_000099', 'Friction in machine mechanisms', 'Engineering & Technology', 'Kinematics of Machinery', 'Technical Concept', 'Resistance to relative motion between contacting machine components, affecting forces, power loss, wear and motion.', 'Dry/sliding friction, rolling resistance, friction laws, lubrication effects and efficiency implications.', 'Energy dissipation; contact mechanics; wear; efficiency.', 'Friction converts mechanical work into heat and can cause wear. Mechanism analysis accounts for friction forces and moments when they materially affect motion or power.', 'Friction; machine elements; Energy dissipation; contact mechanics; wear; efficiency', 'Active'), ('KCR_000100', 'Fins', 'Engineering & Technology', 'Heat and Mass Transfer', 'Technical Concept', 'Extended surfaces used to increase heat-transfer area and enhance heat transfer between a solid and an adjoining fluid.', 'Fin geometry, conduction within the fin, convection boundary condition, efficiency/effectiveness and temperature distribution.', 'Conduction-convection coupling; thermal resistance; surface area.', 'Fins improve heat transfer by increasing effective surface area, with performance governed by fin conductivity, geometry, convection coefficient and temperature difference.', 'Conduction; convection; thermal resistance', 'Active') ON CONFLICT DO NOTHING;